#include <iostream>
#include <vector>
#include <string>

using namespace std;

long long trap(const vector<int>& height) {
    int l = 0, r = (int)height.size() - 1;
    long long ans = 0;
    int leftMax = 0, rightMax = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            if (height[l] >= leftMax) leftMax = height[l];
            else ans += leftMax - height[l];
            ++l;
        } else {
            if (height[r] >= rightMax) rightMax = height[r];
            else ans += rightMax - height[r];
            --r;
        }
    }
    return ans;
}

int main() {
    vector<int> height;
    string s;
    if (!getline(cin, s)) return 0;   // 只读一行，即一个测试样例

    int num = 0;
    bool inNum = false;
    for (char c : s) {
        if (c >= '0' && c <= '9') {          // 逗号分隔：0,1,0,2
            num = num * 10 + (c - '0');
            inNum = true;
        } else {
            if (inNum) { height.push_back(num); num = 0; inNum = false; }
        }
    }
    if (inNum) height.push_back(num);

    cout << trap(height) << endl;
    return 0;
}

